def generate_equi_pattern(r, c, r0, c0):
    """Generate pattern values at (r,c) relative to anchor (r0, c0)"""
    dr = r - r0
    dc = c - c0

    if dr == -2 and -2 <= dc <= 2:
        return 5
    elif dr == -1:
        if abs(dc) == 2:
            return 2
        if dc == 0:
            return 5
    elif dr == 0:
        if abs(dc) == 2:
            return 2
        if dc == 0:
            return 3
    elif dr == 1:
        if abs(dc) == 2:
            return 2
    elif dr == 2:
        if -2 <= dc <= 2:
            return 8
        # Extended 2s outside core
